/* @autogenerated */
import { FormControl, FormGroup } from '@angular/forms';
import { bindFormPrecondition } from './form-precondition';

interface Task {
  status: string | null;
  assignee: { $ref: string } | null;
  title: string;
}

describe('bindFormPrecondition', () => {
  const formOf = (value: Task) =>
    new FormGroup({
      status: new FormControl<string | null>(value.status),
      assignee: new FormControl<{ $ref: string } | null>(value.assignee),
      title: new FormControl<string>(value.title),
    });

  const assignedWhenInProgress = (task: Task) =>
    task.status !== 'in-progress' || (task.assignee?.$ref ?? null) !== null;

  it('marks every involved field when the condition fails', () => {
    const form = formOf({ status: 'in-progress', assignee: null, title: 'A' });
    bindFormPrecondition(form, 'assigned', ['status', 'assignee'], assignedWhenInProgress);

    expect(form.get('status')!.hasError('precondition-assigned')).toBeTrue();
    expect(form.get('assignee')!.hasError('precondition-assigned')).toBeTrue();
    expect(form.get('title')!.errors).toBeNull();
    expect(form.valid).toBeFalse();
  });

  it('clears the error of all involved fields when another one fixes it', () => {
    const form = formOf({ status: 'in-progress', assignee: null, title: 'A' });
    bindFormPrecondition(form, 'assigned', ['status', 'assignee'], assignedWhenInProgress);

    form.get('assignee')!.setValue({ $ref: 'u1' });

    expect(form.get('status')!.errors).toBeNull();
    expect(form.get('assignee')!.errors).toBeNull();
    expect(form.valid).toBeTrue();
  });

  it('fails again when a later change breaks the condition', () => {
    const form = formOf({ status: 'pending', assignee: null, title: 'A' });
    bindFormPrecondition(form, 'assigned', ['status', 'assignee'], assignedWhenInProgress);
    expect(form.valid).toBeTrue();

    form.get('status')!.setValue('in-progress');

    expect(form.get('assignee')!.hasError('precondition-assigned')).toBeTrue();
    expect(form.valid).toBeFalse();
  });

  it('ignores fields that are not in the form', () => {
    const form = formOf({ status: 'in-progress', assignee: null, title: 'A' });
    bindFormPrecondition(form, 'other', ['missing'], () => false);

    expect(form.valid).toBeTrue();
  });
});
